class AuthenticationManager {
 int ttl;unordered_map<string,int> expiry;
public:
 AuthenticationManager(int timeToLive):ttl(timeToLive){}
 void generate(string tokenId,int currentTime){expiry[tokenId]=currentTime+ttl;}
 void renew(string tokenId,int currentTime){
  auto it=expiry.find(tokenId);
  if(it!=expiry.end() && it->second>currentTime)it->second=currentTime+ttl;
 }
 int countUnexpiredTokens(int currentTime){
  int ans=0;for(auto it=expiry.begin();it!=expiry.end();){
   if(it->second<=currentTime)it=expiry.erase(it);
   else {++ans;++it;}
  }return ans;
 }
};
